"""Record actual gameplay techniques at fixed simulation steps, without video interpolation.
CAPTURE_FPS=30 (default), CAPTURE_SECONDS=2.8, CAPTURE_ONLY=comma-separated IDs.
CAPTURE_SIMPLE_STAGE=1 hides buildings for inspection; it does not replace the game rig.
"""
import json,os,subprocess
from pathlib import Path
from playwright.sync_api import sync_playwright
out=Path(os.environ.get('CAPTURE_DIR','/tmp/vergil-comparison-after'));out.mkdir(exist_ok=True)
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader'])
 p=b.new_page(viewport={'width':640,'height':426});errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.on('console',lambda m:errors.append(m.text) if m.type=='error' and ('Shader' in m.text or 'WebGL' in m.text) else None);p.goto(os.environ.get('GAME_URL','http://127.0.0.1:4181/')+'?q=low&dyn=0');p.wait_for_function('window.app?.game?.state==="title"',timeout=240000);p.evaluate('app.stop()');p.get_by_role('button',name='はじめる',exact=True).click()
 if os.environ.get('CAPTURE_SIMPLE_STAGE')=='1':p.evaluate("()=>{const g=app.game,lights=[];g.stage.group.traverse(o=>{if(o.isLight&&lights.length<2)lights.push(o.clone());});g.stage.group.visible=false;for(const l of lights){l.position.set(2,3,126);l.intensity=4;l.castShadow=false;app.scene.add(l);}app.renderer.gl.shadowMap.autoUpdate=false;}")
 p.evaluate('''async()=>{const g=app.game;g.flow.update=()=>{};g.director.clear();g.magic.clear();g.flow._place(g.playerPosition.clone().set(0,0,124),0);await g.weapons.swords.select('mythical');g.hud.setVisible(false);g.touch.setVisible(false);g.player.invulnerable=999;window.poseCamera=()=>{const at=window.captureFixedAt??g.player.character.position,c=app.rig.camera;c.position.set(at.x+2.8,at.y+1.7,at.z+4);c.lookAt(at.x,at.y+1,at.z);if(window.caseKind.startsWith('judgement')||window.caseKind==='end'||window.caseKind.startsWith('phantom')){c.position.set(at.x+3.8,at.y+2,at.z+5.2);c.lookAt(at.x,at.y+1,at.z+1.5);}if(['rising','jump-katana','dive-katana','aerial-b','judgement-air'].includes(window.caseKind)){c.position.y=at.y+2.2;c.lookAt(at.x,at.y+1.8,at.z);c.fov=48;}else c.fov=38;c.updateProjectionMatrix();app.scene.updateMatrixWorld(true);app.post.render();};}''')
 if os.environ.get('CAPTURE_NORMAL_CAMERA')=='1':p.evaluate('window.poseCamera=()=>{app.scene.updateMatrixWorld(true);app.post.render();}')
 cases=p.evaluate("Object.keys(Object.fromEntries(app.game.player.moves.filter(m=>m.action).map(m=>[m.config.id,m])))")
 cases=[c for c in cases if c not in ['cast','kick','jump']] + ['judgement','end','phantom-shot','phantom-orbit','phantom-rain','phantom-burst','phantom-storm','judgement-air','judgement-chain','combo-a','combo-b','combo-c','taunt','flourish','transform','stance','sheath','walk','dodge']
 wanted=os.environ.get('CAPTURE_ONLY');cases=[c for c in cases if not wanted or c in wanted.split(',')]
 durations={}
 for kind in cases:
  folder=out/kind;folder.mkdir(exist_ok=True);rows=[];fps=int(os.environ.get('CAPTURE_FPS','30'));seconds=max(float(os.environ.get('CAPTURE_SECONDS','2.8')),3.8 if kind.startswith('combo-') else 0);durations[kind]=seconds;p.evaluate('window.captureSequence={index:0,last:null,started:0}')
  p.evaluate("""kind=>{const g=app.game,p=g.player;g.input.reset();g.director.clear();p.techniques.reset();p.arts.cancel();p.revive();p.setWeapon('katana');g.flow._place(g.playerPosition.clone().set(0,0,124),0);app.simulate(.2);if(['quickDraw','heavy','stance','walk'].includes(kind)){p.arts.startSheath();app.simulate(2);}window.caseKind=kind;if(kind.startsWith('judgement')||kind==='end'||kind.startsWith('phantom')){const a=g.director.spawn('ashigaru',0,127,Math.PI);a.hp=a.maxHp=10000;a.maxPosture=10000;a.cooldown=999;a.update=()=>{};p.lockTarget=a.enemy;}if(kind==='quickDraw'||kind==='heavy'||kind==='stance')g.input.press('attack');else if(kind==='judgement-air'){p.character.hop.start();app.simulate(.06);p.techniques.startRitual(false);}else if(kind==='judgement-chain'){p.mp=100;p.techniques.startRitual(false);}else if(kind.startsWith('combo-')){p._nextCombo();window.captureSequence.started=1;}else if(kind==='judgement'||kind==='end')p.techniques.startRitual(kind==='end');else if(kind.startsWith('phantom'))p.techniques.summon({'phantom-shot':0,'phantom-orbit':1,'phantom-rain':2,'phantom-burst':'burst','phantom-storm':'storm'}[kind]);else if(kind==='flourish')p.arts.startSheath(true);else if(kind==='transform'){p.special=1;g.input.press('special');g.input.release('special');}else if(kind==='taunt')p.techniques.startTaunt();else if(kind==='sheath')p.arts.startSheath();else if(kind==='walk')g.input.keys.add('KeyW');else if(kind==='dodge')p._startDodge();else{const m=p.moves.find(m=>m.config.id===kind);if(m?.config.airborne)p.character.hop.start();if(m)p._startMove(m,null);}}""",kind)
  if os.environ.get('CAPTURE_END_HIGH_FRAME')=='1' and kind=='end':p.evaluate("window.captureHighBlade=true;const old=poseCamera;window.poseCamera=()=>{old();if(window.caseKind!=='end')return;const at=window.captureFixedAt??app.game.player.character.position,c=app.rig.camera;c.position.set(at.x+3.8,at.y+2.4,at.z+5.2);c.lookAt(at.x,at.y+1.5,at.z+.8);c.fov=44;c.updateProjectionMatrix();app.scene.updateMatrixWorld(true);app.post.render();};")
  if os.environ.get('CAPTURE_FIXED_CAMERA')=='1':p.evaluate('window.captureFixedAt=app.game.player.character.position.clone()')
  for i in range(round(seconds*fps)):
   row=p.evaluate("""({i,kind,fps})=>{const g=app.game,p=g.player;if(kind==='judgement-chain'){const r=p.techniques.ritual;if(r&&!r.queued&&r.chain<3&&r.t>=.45){g.input.press('weapon');g.input.release('weapon');}}if(kind.startsWith('combo-')){const seq=window.captureSequence,move=p.move,delay=kind==='combo-a'?0:kind==='combo-b'?.15:.25;if(seq.started<5&&p._canChain()&&(!delay||p.state==='free'&&p.stateTime>=delay)){g.input.press('attack');g.input.release('attack');seq.started++;}if(seq.started===5&&p.state==='free'&&!seq.sheathed){p.arts.startSheath();seq.sheathed=true;}}if(i===(kind==='quickDraw'?1:Math.round(.65*fps))&&kind!=='stance')g.input.release('attack');app.simulate((1/fps)*(1-1e-10),1/60);poseCamera();const c=p.character,blade=g.heroPresence.katanaSheath.copy?.visible?g.heroPresence.katanaSheath.copy:g.weapons.blade(),hand=c.getBone('RightHand'),left=c.getBone('LeftHand'),v=c.position.clone(),q=c.root.quaternion.clone(),grip=blade?blade.localToWorld(v.set(0,0,-.1)):null,direction=blade?v.clone().set(0,0,1).applyQuaternion(blade.getWorldQuaternion(q)):null;return {hidden:p.techniques.hidden,heroVisible:c.root.visible,flyingSlashes:p.techniques.assets.flyPool.filter(s=>s.mesh.visible).map(s=>({position:s.mesh.position.toArray(),opacity:s.mesh.material.uniforms.uOpacity.value})),contact:{rightGap:grip&&hand?grip.distanceTo(hand.getWorldPosition(v.clone())):null,leftGap:left?left.getWorldPosition(v.clone()).distanceTo(g.heroPresence.sheath.getWorldPosition(v.clone())):null,bladeDirection:direction?.toArray()},t:(i+1)/fps,mode:p.arts.mode,move:p.move?.config.id,phase:p.move?.phase,ritual:p.techniques.ritual?{time:p.techniques.ritual.t,chargeRemaining:p.techniques.ritual.chargeRemaining,chain:p.techniques.ritual.chain,struck:p.techniques.ritual.struck,airborne:p.techniques.ritual.airborne}:null,effects:{slash:p.techniques.assets.slashPool?.filter(s=>s.mesh.visible).map(s=>({opacity:s.mesh.material.opacity,scale:s.mesh.scale.x,position:s.mesh.position.toArray()}))??[],burst:p.techniques.assets.burstPool?.filter(s=>s.mesh.visible).map(s=>({opacity:s.mesh.material.opacity,scale:s.mesh.scale.x,position:s.mesh.position.toArray()}))??[],rift:p.techniques.assets.riftPool?.filter(s=>s.mesh.visible).map(s=>({opacity:s.mesh.material.opacity,scale:s.mesh.scale.x,position:s.mesh.position.toArray()}))??[],end:p.techniques.assets.endPool.filter(s=>s.mesh.visible).map(s=>({opacity:s.mesh.material.opacity,scale:s.mesh.scale.x,position:s.mesh.position.toArray()}))},travelRibbon:{visible:p.techniques.assets.travelMesh.visible,opacity:p.techniques.assets.travelMesh.material.uniforms.uOpacity.value,position:p.techniques.assets.travelMesh.position.toArray()},clouds:[...p.techniques.assets.riftPool,...p.techniques.assets.endPool].filter(s=>s.mesh.visible).map(s=>({opacity:s.aura.material.uniforms.uOpacity.value,bolts:s.bolts.material.uniforms.uOpacity.value,age:s.duration-s.life,kind:s.kind})),afterimages:p.techniques.afterimages.pool.filter(s=>s.pivot.visible).map(s=>({position:s.pivot.position.toArray(),opacity:s.material.opacity,progress:1-s.life/s.duration,clip:s.action?.getClip().name??null})),projectiles:p.techniques.projectiles.length,root:c.position.toArray(),traversal:{active:p.techniques.traversal.active,lift:p.techniques.traversal.lift},recovery:{active:p.arts.endRecovery??false,lift:g.heroPresence.endRecoveryLift??0},flashes:p.techniques.assets.burstPool.filter(s=>s.flash.visible).map(s=>({opacity:s.flash.material.uniforms.uOpacity.value,scale:s.flash.scale.x,position:s.flash.position.toArray()})),airHeight:c.airHeight,sheath:g.heroPresence.sheath.getWorldPosition(c.position.clone()).toArray(),rig:Object.fromEntries([...new Set(c.bones.values())].map(b=>[b.name,{quaternion:b.quaternion.toArray(),position:b.getWorldPosition(c.position.clone()).toArray()}])),bones:Object.fromEntries(['Hips','Spine2','Head','RightArm','RightForeArm','RightHand','LeftArm','LeftForeArm','LeftHand','LeftFoot','RightFoot'].map(n=>[n,c.getBone(n).getWorldPosition(c.position.clone()).toArray()]))};}""",{'i':i,'kind':kind,'fps':fps});rows.append(row);p.screenshot(path=str(folder/f'{i:03}.png'))
  assert all(all(__import__('math').isfinite(v) for a in bone.values() for v in a) for row in rows for bone in row['rig'].values()), kind+' contains invalid skeleton values'
  if kind=='end':
   waist=[r for r in rows if r['ritual'] and not r['ritual'].get('chargeRemaining',0) and .14<=r['ritual']['time']<2.52]
   assert waist,'No waist-pose frames captured'
   assert max(r['contact']['rightGap'] for r in waist)<.001,'Right hand left the authored handle anchor'
   assert max(r['contact']['leftGap'] for r in waist)<.001,'Left hand left the scabbard mouth'
   assert max(abs(r['contact']['bladeDirection'][1]) for r in waist)<.001,'Waist cut became vertical'
   if seconds>=6.5:
    burst=next(r['t'] for r in rows if r['effects']['burst'])
    assert abs(burst-5.5)<=.08,('Final burst missed the compressed reference clock',burst)
    assert any(r['flyingSlashes'] for r in rows),'Missing purple flying slashes'
    assert all(not r['heroVisible'] and not r['afterimages'] for r in rows if r['hidden']),'Body remained during invisible cuts'
    assert rows[-1]['heroVisible'],'Body did not return'
    assert any(c['kind']=='end' and c['opacity']>0 for r in rows for c in r['clouds']),'Missing field clouds'
    assert not rows[-1]['travelRibbon']['visible'] and not rows[-1]['afterimages'] and not rows[-1]['clouds'],'Effects remained after the technique'

  (out/(kind+'-timeline.json')).write_text(json.dumps(rows,indent=2))
  subprocess.run(['ffmpeg','-y','-framerate',str(fps),'-i',str(folder/'%03d.png'),'-vf',"drawtext=text='"+kind+" - local revised capture':x=12:y=12:fontsize=16:fontcolor=white:box=1:boxcolor=black@0.7",'-c:v','libx264','-pix_fmt','yuv420p',str(out/(kind+'.mp4')),'-loglevel','error'],check=True)
  print(json.dumps({'recorded':kind,'fps':fps,'frames':len(rows)}),flush=True)
 assert not errors,errors
 (out/'capture-settings.json').write_text(json.dumps({'fps':fps,'secondsPerCase':durations,'cases':cases,'pageErrors':errors,'simulationHz':60,'interpolated':False,'normalGameCamera':os.environ.get('CAPTURE_NORMAL_CAMERA')=='1','highBladeInspectionCamera':os.environ.get('CAPTURE_END_HIGH_FRAME')=='1'},indent=2))
 b.close()
